def _enumerate_paths(nN, E, S, B):
    camps = set(B)
    paths = []
    def extend(path):
        i = path[-1]
        if i in camps:
            paths.append(list(path))
            return
        for j in range(nN):
            if E[i][j] and j not in path:
                extend(path + [j])
    for s in S:
        extend([s])
    return paths
paths = _enumerate_paths(nN, E, S, B)
